import{_ as a,o as t,c as o,ag as s}from"./chunks/framework.DCk0k6gb.js";const h=JSON.parse('{"title":"sa-token-rust","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),n={name:"index.md"};function r(i,e,c,d,l,p){return t(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="sa-token-rust" tabindex="-1">sa-token-rust <a class="header-anchor" href="#sa-token-rust" aria-label="Permalink to &quot;sa-token-rust&quot;">​</a></h1><p><a href="/sa-token-rust/zh/">中文</a></p><p>Lightweight authentication and authorization for Rust. Inspired by <a href="https://github.com/dromara/sa-token" target="_blank" rel="noreferrer">Dromara sa-token</a>; this tree is an independent implementation (MIT OR Apache-2.0). See <code>NOTICE</code> at the repository root.</p><p>It targets Web and gRPC: the same <code>StpUtil</code> / <code>SaTokenState</code> model works across Axum, Actix-web, Poem, Rocket, Warp, Salvo, Tide, Gotham, Ntex, and Tonic.</p><p><strong>Start here:</strong> <a href="/sa-token-rust/guide/quick-start.html">Quick start</a>. Upgrading from 0.1.x: <a href="/sa-token-rust/guide/migration-0.2.html">Migrate to 0.2</a>.</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><p>Login, logout, kick-out, and replace flows are orchestrated by <code>AuthService</code>. Application code usually calls the static façade: <code>StpUtil::login</code>, <code>logout</code>, <code>kick_out</code>. Example: <code>let token = StpUtil::login(&quot;10001&quot;).await?;</code></p><p>Permissions and roles go through <code>AuthzService</code>. Use <code>has_permission</code> / <code>check_role</code> in code, or attach macros such as <code>#[sa_check_permission(&quot;user:add&quot;)]</code>. Wildcard vs exact matching is covered in <a href="/sa-token-rust/guide/permission-matching.html">Permissions and macros</a>.</p><p>Path-level middleware auth uses <code>PathAuthConfig</code>. Public routes must be listed in <code>exclude</code>. <code>#[sa_ignore]</code> only skips macro-inserted checks; it does <strong>not</strong> bypass the Layer or middleware. See <a href="/sa-token-rust/guide/path-auth.html">Path auth</a>.</p><p>Memory, Redis, and Database backends go through <code>SaTokenDao</code>. Switch backends with plugin Cargo features; key layout is owned by <code>SaKeys</code>. Token read/write goes through core <code>token_io</code> (<code>read_token</code> / <code>write_token_cookie</code>), shared by all framework adapters.</p><p>JWT, nonce, refresh tokens, OAuth2 (with PKCE), SSO, WebSocket auth, online presence, distributed sessions, and the event bus each have dedicated guides.</p><p>Multi-account isolation uses <code>login_type</code>, for example admin vs user. Prefer <code>StpUtil::builder(...).login_type(&quot;admin&quot;)</code>, or bind a façade with <code>SaLogic::new(&quot;admin&quot;, manager)</code>.</p><h2 id="project-layout" tabindex="-1">Project layout <a class="header-anchor" href="#project-layout" aria-label="Permalink to &quot;Project layout&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sa-token-rust/</span></span>
<span class="line"><span>├── sa-token-core/           # Dao, keys, service, token_io, oauth2/, sso/, StpUtil, SaLogic</span></span>
<span class="line"><span>├── sa-token-adapter/        # SaStorage, SaSerializer, SaRequest / SaResponse, scan</span></span>
<span class="line"><span>├── sa-token-macro/          # Procedural macros</span></span>
<span class="line"><span>├── sa-token-plugin-common/  # SaTokenState, rejection helpers (re-exported by plugins)</span></span>
<span class="line"><span>├── sa-token-storage-*/      # memory / redis / database</span></span>
<span class="line"><span>├── sa-token-plugin-*/       # axum, actix-web, poem, rocket, warp, salvo, tide, gotham, ntex, tonic</span></span>
<span class="line"><span>└── doc/                     # This site (VitePress)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>Facade crates (Actix-web, Rocket, Salvo, Gotham, Ntex) select the framework major version via Cargo features. Shared types live in <code>sa-token-plugin-common</code>; there are no <code>*-core</code> crates anymore.</p><h2 id="community" tabindex="-1">Community <a class="header-anchor" href="#community" aria-label="Permalink to &quot;Community&quot;">​</a></h2><ul><li>GitHub: <a href="https://github.com/sa-tokens/sa-token-rust" target="_blank" rel="noreferrer">https://github.com/sa-tokens/sa-token-rust</a></li><li>Issues: <a href="https://github.com/sa-tokens/sa-token-rust/issues" target="_blank" rel="noreferrer">https://github.com/sa-tokens/sa-token-rust/issues</a></li></ul><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><p>MIT OR Apache-2.0. See <code>LICENSE-MIT</code> and <code>LICENSE-APACHE</code>.</p>`,19)])])}const m=a(n,[["render",r]]);export{h as __pageData,m as default};
